const toastEl=document.getElementById('toast');let toastTimer;function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2600)}
const authScreen=document.getElementById('authScreen'),appShell=document.getElementById('appShell'),authForm=document.getElementById('authForm');let authMode='login';
function showAuth(mode='login'){authMode=mode;authScreen.classList.add('show');appShell.style.display='none';document.getElementById('authMessage').classList.remove('show');document.getElementById('authBack').style.display=mode==='forgot'?'inline-block':'none';document.getElementById('authTitle').textContent=mode==='signup'?'Crie sua conta':mode==='forgot'?'Recuperar senha':'Bem-vinda de volta';document.getElementById('authSubtitle').textContent=mode==='signup'?'Comece a organizar sua operação de afiliados.':mode==='forgot'?'Vamos enviar as instruções para o seu e-mail.':'Acesse sua conta para continuar.';document.getElementById('nameField').style.display=mode==='signup'?'grid':'none';document.getElementById('passwordField').style.display=mode==='forgot'?'none':'grid';document.getElementById('authPassword').required=mode!=='forgot';document.getElementById('loginOptions').style.display=mode==='login'?'flex':'none';document.getElementById('authSubmit').textContent=mode==='signup'?'Criar minha conta  →':mode==='forgot'?'Enviar instruções  →':'Entrar na plataforma  →';document.getElementById('authSwitch').style.display=mode==='forgot'?'none':'block';document.getElementById('authSwitch').innerHTML=mode==='signup'?'Já tem uma conta? <button class="auth-link" id="signupLink">Entrar</button>':'Ainda não tem uma conta? <button class="auth-link" id="signupLink">Criar conta grátis</button>';document.getElementById('signupLink').onclick=()=>showAuth(mode==='signup'?'login':'signup');}
showAuth('login');document.getElementById('authBack').onclick=()=>showAuth('login');document.getElementById('forgotPassword').onclick=()=>showAuth('forgot');document.getElementById('togglePassword').onclick=()=>{const p=document.getElementById('authPassword');p.type=p.type==='password'?'text':'password';document.getElementById('togglePassword').textContent=p.type==='password'?'Mostrar':'Ocultar'};
authForm.addEventListener('submit',e=>{e.preventDefault();const msg=document.getElementById('authMessage');const email=document.getElementById('authEmail').value;if(authMode==='forgot'){msg.textContent=`Se ${email} estiver cadastrado, você receberá instruções para redefinir sua senha.`;msg.classList.add('show');return}if(document.getElementById('authPassword').value.length<6){msg.textContent='A senha deve ter pelo menos 6 caracteres.';msg.classList.add('show');return}authScreen.classList.remove('show');appShell.style.display='flex';toast(authMode==='signup'?'Conta de demonstração criada. Bem-vinda!':'Acesso de demonstração realizado. Bem-vinda, Mariana!')});
function showModal(){document.getElementById('overlay').classList.add('show')}function hideModal(){document.getElementById('overlay').classList.remove('show')}
document.getElementById('announceBtn').onclick=showModal;document.getElementById('closeModal').onclick=hideModal;document.getElementById('cancelModal').onclick=hideModal;document.getElementById('overlay').addEventListener('click',e=>{if(e.target.id==='overlay')hideModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideModal()});
document.getElementById('announceForm').addEventListener('submit',e=>{e.preventDefault();const title=document.getElementById('title').value;const audience=document.getElementById('audience').value;hideModal();e.target.reset();toast(`Comunicado “${title}” enviado para ${audience.toLowerCase()}.`)});
document.getElementById('nav').addEventListener('click',e=>{const b=e.target.closest('button[data-page]');if(!b)return;if(b.dataset.page==='Afiliados'){window.location.href='affiliates.php';return}document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('breadcrumb').textContent=b.dataset.page;document.getElementById('sidebar').classList.remove('open');if(b.dataset.page!=='Visão geral')toast(`${b.dataset.page} — seção demonstrativa do protótipo.`)});
document.querySelectorAll('[data-nav]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const target=document.querySelector(`[data-page="${a.dataset.nav}"]`);if(target)target.click()}));
document.querySelectorAll('[data-toast]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.toast)));document.getElementById('notifBtn').onclick=()=>toast('Você está em dia. Nenhuma nova notificação.');document.getElementById('exportBtn').onclick=()=>toast('Relatório de outubro preparado para exportação.');document.getElementById('menuBtn').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
document.getElementById('period').addEventListener('change',e=>toast(`Período atualizado: ${e.target.value.toLowerCase()}.`));
document.getElementById('globalSearch').addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase('pt-BR');document.querySelectorAll('#affiliateRows tr').forEach(row=>row.style.display=row.innerText.toLocaleLowerCase('pt-BR').includes(q)?'':'none')});
